'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['createObservableRecord']);
const { createObservableRecord } = api;

for (const invalid of [null, undefined, [], 'record', 1, true]) {
  assert.throws(() => createObservableRecord(invalid), TypeError);
}

const initial = { count: 1, label: 'start' };
const record = createObservableRecord(initial);
assert.deepStrictEqual(Object.keys(record).sort(), ['get', 'set', 'subscribe']);
assert.strictEqual(record.get('count'), 1);
assert.strictEqual(record.get('missing'), undefined);

initial.count = 99;
initial.added = true;
assert.strictEqual(record.get('count'), 1);
assert.strictEqual(record.get('added'), undefined);

const events = [];
const unsubscribeFirst = record.subscribe((key, value, previous) => {
  events.push(['first', key, value, previous]);
});
const unsubscribeSecond = record.subscribe((key, value, previous) => {
  events.push(['second', key, value, previous]);
});

record.set('count', 2);
assert.strictEqual(record.get('count'), 2);
assert.deepStrictEqual(events, [
  ['first', 'count', 2, 1],
  ['second', 'count', 2, 1]
]);

record.set('count', 2);
assert.deepStrictEqual(events.slice(2), [
  ['first', 'count', 2, 2],
  ['second', 'count', 2, 2]
]);

unsubscribeFirst();
unsubscribeFirst();
record.set('label', 'next');
assert.deepStrictEqual(events.slice(4), [
  ['second', 'label', 'next', 'start']
]);
unsubscribeSecond();

assert.throws(() => record.subscribe(null), TypeError);
assert.throws(() => record.subscribe({}), TypeError);

{
  const observable = createObservableRecord({ n: 0 });
  const calls = [];
  let unsubscribeB;
  observable.subscribe(() => {
    calls.push('A');
    unsubscribeB();
    observable.subscribe(() => calls.push('C'));
  });
  unsubscribeB = observable.subscribe(() => calls.push('B'));

  observable.set('n', 1);
  assert.deepStrictEqual(calls, ['A', 'B']);

  calls.length = 0;
  observable.set('n', 2);
  assert.deepStrictEqual(calls, ['A', 'C']);
}

{
  const observable = createObservableRecord({ x: 1 });
  const calls = [];
  const listener = () => calls.push('same');
  const removeOne = observable.subscribe(listener);
  observable.subscribe(listener);
  removeOne();
  observable.set('x', 3);
  assert.deepStrictEqual(calls, ['same']);
}

